const vttContent = $input.item.json.data;
const lines = vttContent.split('\n');
const subtitles = [];
let currentTime = '';
let currentText = '';

const cleanText = (text) => {
  return text.replace(/<[^>]+>/g, '').trim();
};

for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();

  if (line.includes('-->')) {
    currentTime = line;
    // Look ahead for text on the next lines
    let textLines = [];
    for (let j = i + 1; j < lines.length; j++) {
        const nextLine = lines[j].trim();
        if (nextLine === '' || nextLine.includes('-->')) {
            break;
        }
        textLines.push(cleanText(nextLine));
    }
    currentText = textLines.join(' ');

    if (currentTime && currentText) {
      subtitles.push({ time: currentTime, text: currentText });
      currentTime = '';
      currentText = '';
    }
  }
}

// Deduplicate based on text to avoid re-translating the same content
const uniqueSubtitles = [];
const seenTexts = new Set();
for (const sub of subtitles) {
  if (!seenTexts.has(sub.text)) {
    uniqueSubtitles.push(sub);
    seenTexts.add(sub.text);
  }
}

return uniqueSubtitles.map(item => ({ json: item }));

const items = $input.all();
let vttString = "WEBVTT\nKind: captions\nLanguage: zh-CN\n\n";

for (const item of items) {
  const original = item.json.pairedItem.json;
  const translatedText = item.json.text;

  vttString += original.time + '\n';
  vttString += translatedText + '\n\n';
}

$item.json.translatedVtt = vttString;

return $item;

