const fs = require('fs');
const path = require('path');

const item = $input.item;
const translatedVtt = item.json.translatedVtt;

// Hardcode the original filename and create the new one
const originalFileName = 'Docs/[CVPR 2024 highlight] FoundationPose： Unified 6D Pose Estimation and Tracking of Novel Objects [Ip_yWsGUF6c].en.vtt';
const newFileName = originalFileName.replace('.en.vtt', '.zh-CN.vtt');

// n8n's execution root is the project root, so the relative path is correct.
const filePath = path.resolve(newFileName);

fs.writeFileSync(filePath, translatedVtt);

// Return something to show success
item.json.newFileName = newFileName;
return item;
